"""Self-contained, interactive ancestry/QC report with visible evidence limits."""
import html
import json
from pathlib import Path

COLORS=['#308a9f','#eeaa49','#b570a4','#527a57','#de775e','#7378b2']
E=lambda x:html.escape(str(x))


def render(folder,data):
    sample=data['sample'];adm=data['admixture'];mt=data['mitochondrial'];neo=data['neanderthal'];qc=data['qc']
    composition=adm['components'];stops=[];start=0;bars=[]
    for i,c in enumerate(composition):
        end=start+c['fraction']*100;stops.append(f'{COLORS[i]} {start:.5f}% {end:.5f}%');start=end
        bars.append(f'<li><div class="label"><span><i style="background:{COLORS[i]}"></i>{E(c["component"])}</span><strong>{100*c["fraction"]:.1f}%</strong></div><div class="track"><div style="width:{100*c["fraction"]:.3f}%;background:{COLORS[i]}"></div></div><small>Chromosome interval {100*c["lower"]:.1f}–{100*c["upper"]:.1f}%</small></li>')
    gradient='conic-gradient('+','.join(stops)+')' if stops else '#e4e9e9'
    group=mt.get('haplogroup') or 'Unresolved'
    quality=f'{100*mt["classification_quality"]:.1f}%' if mt.get('classification_quality') is not None else 'Not estimated'
    depth=qc.get('mean_autosomal_depth_after_filters');covered=qc.get('autosomal_fraction_covered')
    covtext=f'{100*covered:.1f}%' if covered is not None else 'Not available'
    depthtext=f'{depth:.2f}×' if depth is not None else 'Not available'
    def note(s):return '<p class="note">'+E(s)+'</p>'
    def link(suffix,title):
        if not (Path(folder)/(sample+suffix)).is_file():return ''
        return '<a class="download" href="'+E(sample+suffix)+'">'+E(title)+'</a>'
    sources=[('Reference model, population definitions and validation',data['resources']['model_source']),
             ('ADMIXTURE method','https://doi.org/10.1101/gr.094052.109'),
             ('Haplogrep 3 method','https://pmc.ncbi.nlm.nih.gov/articles/PMC10320078/'),
             ('Mitochondrial reference tree','https://github.com/genepi/phylotree-rcrs-17'),
             ('Neanderthal marker study and data','https://www.nature.com/articles/s41586-020-2225-9')]
    population='<div class="composition"><div class="donut" style="background:'+gradient+'"><div><b>K = 6</b><span>reference model</span></div></div><ul class="bars">'+''.join(bars)+'</ul></div>' if composition else note(adm.get('reason','Population fractions unavailable.'))
    mtcoverage=100*mt.get('callable_fraction',0)
    carried_text=f"{neo['carried_markers']:,}" if neo['callable_markers'] else 'Unresolved'
    copies_text=f"{neo['derived_allele_copies']:,} derived allele copies were called across these sites." if neo['callable_markers'] else 'An allele-copy total is unavailable because no catalog sites were callable.'
    mt_depth=f"{mt['mean_depth']:.1f}×" if 'mean_depth' in mt else 'Not available'
    head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+E(sample)+''' · Ancestry & DNA quality</title><style>
:root{--ink:#193a40;--teal:#166f72;--muted:#607478;--paper:#f4f5f0;--line:#dce5df}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,sans-serif}a{color:var(--teal)}header{padding:28px 6vw 48px;background:#e2eeea}header .brand{letter-spacing:.18em;text-transform:uppercase;font-size:12px;font-weight:700}h1{font-size:clamp(30px,4vw,52px);letter-spacing:-.04em;font-weight:650;margin:24px 0 4px;line-height:1.15}h2{font-size:30px;letter-spacing:-.03em;line-height:1.25;margin-top:0}h3{font-size:19px}header p{max-width:720px}.tag{display:inline-block;border:1px solid #a9c6be;border-radius:20px;padding:3px 12px;font-size:12px;margin:10px 6px 0 0}nav{position:sticky;top:0;display:flex;gap:7px;padding:14px 6vw;background:#fffefbf2;backdrop-filter:blur(8px);border-bottom:1px solid var(--line);overflow:auto;z-index:2}button{background:transparent;border:0;border-radius:24px;color:var(--muted);padding:9px 16px;font:inherit;cursor:pointer;white-space:nowrap}button[aria-selected=true]{background:var(--teal);color:white}main{max-width:1250px;margin:0 auto;padding:32px 24px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-bottom:24px}article,section{background:white;border:1px solid var(--line);border-radius:18px;padding:30px;margin-bottom:22px}article{margin:0}.eyebrow{text-transform:uppercase;letter-spacing:.11em;font-size:11px;font-weight:700;color:var(--muted)}.big{font-size:38px;font-weight:650;line-height:1.2;margin:12px 0}.muted,small{color:var(--muted)}.note{background:#eff5f2;border-left:3px solid #88aca0;padding:16px 20px;border-radius:0 10px 10px 0;font-size:14px}.composition{display:grid;grid-template-columns:1fr 1.5fr;gap:50px;align-items:center}.donut{width:260px;height:260px;max-width:100%;border-radius:50%;display:grid;place-items:center;margin:auto}.donut>div{width:170px;height:170px;border-radius:50%;background:white;display:flex;flex-direction:column;justify-content:center;text-align:center}.donut b{font-size:34px}.donut span{font-size:13px;color:var(--muted)}.bars{list-style:none;padding:0;margin:0}.bars li{margin:13px 0}.label{display:flex;justify-content:space-between;gap:18px}.label i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:8px}.track{background:#eef1ef;height:8px;border-radius:8px;overflow:hidden;margin:7px 0}.track>div{height:100%;border-radius:8px}small{font-size:12px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:35px}.lineage{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:25px 0}.lineage span{padding:12px 22px;background:#e9f1ed;border-radius:30px}.lineage .end{background:var(--teal);color:white}.metricrow{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.metricrow p{background:#f3f6f3;padding:18px;border-radius:12px}.metricrow strong{display:block;font-size:28px}.download{display:inline-block;padding:8px 14px;border:1px solid #bbcec4;border-radius:8px;margin:5px 8px 5px 0;text-decoration:none;font-size:14px}details{border-top:1px solid var(--line);padding-top:18px;margin-top:20px}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:420px;overflow:auto;background:#f4f7f5;padding:15px}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid var(--line);padding:9px;text-align:left}footer{padding:10px 25px 35px;text-align:center;color:var(--muted);font-size:13px}[hidden]{display:none!important}@media(max-width:800px){.cards,.columns,.composition{grid-template-columns:1fr}.composition{gap:22px}main{padding:20px 12px}article,section{padding:24px}nav{padding:10px 12px}}@media print{nav,button,.download{display:none}body{background:white}main{max-width:none;padding:0}section[hidden],div[hidden]{display:block!important}section{break-inside:avoid;border:0}.cards{grid-template-columns:repeat(3,1fr)}header{padding:20px}pre{max-height:none}}
</style></head><body><header><div class="brand">Genome explorer · '''+E(sample)+'''</div><h1>Your ancestry, with the evidence.</h1><p>Explore broad population composition, one maternal lineage and ancient DNA markers, alongside the quality of the sequencing behind them.</p><span class="tag">GRCh38</span><span class="tag">Low-pass WGS + GLIMPSE2</span><span class="tag">Research estimates</span></header><nav role="tablist" aria-label="Report sections">'''
    tabs=[('overview','Overview'),('population','Population'),('maternal','Maternal line'),('ancient','Neanderthal markers'),('quality','DNA quality'),('methods','Methods & sources')]
    nav=''.join(f'<button role="tab" id="tab-{k}" aria-controls="{k}" aria-selected="{str(i==0).lower()}" data-tab="{k}">{v}</button>' for i,(k,v) in enumerate(tabs))
    overview=f'''<div class="panel" id="overview" role="tabpanel" aria-labelledby="tab-overview"><div class="cards"><article><div class="eyebrow">Population composition</div><div class="big">{adm['matched_markers']:,}</div><p>Matched reference SNPs</p><small>{E(adm['status'].replace('_',' '))}</small></article><article><div class="eyebrow">Maternal haplogroup</div><div class="big">{E(group)}</div><p>One branch of your maternal family line</p><small>{mtcoverage:.1f}% of mitochondrial bases callable</small></article><article><div class="eyebrow">Neanderthal-associated</div><div class="big">{carried_text}</div><p>Markers with a carried derived allele</p><small>Across {neo['callable_markers']:,} callable markers; no genome percentage estimated</small></article></div><section><h2>Broad population composition</h2>{population}{note(adm['scope'])}</section><section><h2>How much DNA was observed?</h2><div class="metricrow"><p><strong>{depthtext}</strong>Mean filtered autosomal depth</p><p><strong>{covtext}</strong>Autosomal bases covered by reads</p></div><p>Imputation uses reference haplotypes to estimate genotypes between sparse reads. It improves marker coverage, while uncertainty and reference bias remain.</p></section></div>'''
    pop=f'''<section class="panel" id="population" role="tabpanel" aria-labelledby="tab-population" hidden><div class="eyebrow">Broad ancestry · exploratory</div><h2>Reference population composition</h2>{population}{note(adm['interval_scope'])}<p>Six broad components are fitted to public reference allele frequencies after exact allele matching. Only genotypes with GP ≥ 0.95 and site INFO ≥ 0.80 contribute. {adm['matched_markers']:,} of {adm['reference_markers']:,} model markers passed.</p><p>The Indigenous American component reflects the reference populations used by this model; it cannot identify a tribe or community. Middle Eastern and North African populations have no separate component and can be distributed across other categories. Small components may be model artifacts.</p>{link('.ancestry_markers.tsv.gz','Download matched marker evidence')}<details><summary>Chromosome stability</summary><pre>{E(json.dumps({'chromosome_markers':adm['chromosome_counts'],'jackknife':adm.get('jackknife',{})},indent=2))}</pre></details></section>'''
    regional=data.get('regional_similarity',{})
    if regional.get('populations'):
        rows=''.join('<tr><td>'+str(r['rank'])+'</td><td>'+E(r['population_name'])+' ('+E(r['population'])+')</td><td>'+str(r['reference_n'])+'</td><td>'+f"{r['distance']:.4f}"+'</td><td>'+str(r['first_in_chromosome_jackknifes'])+'/'+str(regional['chromosomes'])+'</td></tr>' for r in regional['populations'])
        regional_html='<h3>More detailed reference population similarity</h3><p>'+E(regional['scope'])+'</p><p>'+str(regional['markers'])+' exact, spaced SNPs compared across '+str(regional['chromosomes'])+' autosomes. Lower distance means closer similarity. The last column counts how often a group ranked first when one chromosome was omitted; it is not an ancestry probability.</p><div style="overflow-x:auto"><table style="min-width:780px"><thead><tr><th>Rank</th><th>Reference group</th><th>Reference N</th><th>Distance</th><th>Chromosome stability</th></tr></thead><tbody>'+rows+'</tbody></table></div>'+link('.population_similarity.tsv','Download population comparison')
        pop=pop.replace('<details><summary>Chromosome stability',regional_html+'<details><summary>Chromosome stability')
    annotation_url='../../special_annotations/'+sample+'.special_annotations/'+sample+'.special_annotations.html'
    context=mt.get('geographic_context',{})
    context_html='<h3>Maternal origin in the literature</h3><p>'+E(context.get('text','Regional context is unavailable.'))+'</p>'
    if context.get('source'):context_html+='<p><a href="'+E(context['source'])+'">Read the lineage source</a></p>'
    maternal=f'''<section class="panel" id="maternal" role="tabpanel" aria-labelledby="tab-maternal" hidden><div class="eyebrow">Mitochondrial DNA</div><h2>Your maternal lineage: {E(group)}</h2><div class="lineage"><span>Earlier maternal ancestors</span>→<span>Your mother</span>→<span class="end">You · {E(group)}</span></div><p>Mitochondrial DNA traces one maternal line. Haplogrep compares the callable mutations with a mitochondrial phylogenetic tree. The haplogroup is a lineage label; it does not establish a recent country of origin or describe all your ancestors.</p><div class="metricrow"><p><strong>{quality}</strong>Haplogrep classification quality</p><p><strong>{mtcoverage:.1f}%</strong>Mitochondrial bases callable</p></div><p>Classification quality measures agreement with the tree, not a calibrated probability that a geographic origin is correct. Depth ≥ 10 and dominant allele fraction ≥ 90% are required per base. Uncertain positions are excluded from the typed range.</p>{context_html}{note(mt.get('scope',mt.get('reason','Mitochondrial lineage unavailable.')))}{link('.mitochondrial_variants.tsv','Review mitochondrial variants')}{link('.haplogrep.tsv','Review lineage matches') if mt.get('hits') else ''}<details><summary>Lineage evidence and alternative matches</summary><pre>{E(json.dumps(mt,indent=2))}</pre></details></section>'''
    ancient=f'''<section class="panel" id="ancient" role="tabpanel" aria-labelledby="tab-ancient" hidden><div class="eyebrow">Ancient DNA signals</div><h2>Neanderthal-associated markers</h2><div class="metricrow"><p><strong>{carried_text}</strong>Marker sites with at least one derived allele</p><p><strong>{neo['callable_markers']:,}</strong>Callable catalog sites</p></div><p>{copies_text} The screened catalog contains {neo['catalog_markers']:,} eligible SNPs; sites without confident matching genotypes remain unknown.</p>{note(neo['scope'])}<h3>Genome-wide Neanderthal content: not estimated</h3><p>Counting marker alleles cannot measure how much of your genome is in inherited archaic segments. This report therefore has no genome percentage, chromosome painting or ranking against other people. It also does not attribute personality or disease to these markers.</p>{link('.neanderthal_markers.tsv.gz','Download every callable marker')}</section>'''
    maternal=maternal.replace('</section>','<p><a class="download" href="'+annotation_url+'">Annotated mitochondrial variants · Excel and VCF</a></p></section>')
    ancient=ancient.replace('</section>','<p><a class="download" href="'+annotation_url+'">Annotated carried Neanderthal markers · Excel and VCF</a></p></section>')
    quality_panel=f'''<section class="panel" id="quality" role="tabpanel" aria-labelledby="tab-quality" hidden><div class="eyebrow">Evidence behind the estimates</div><h2>DNA quality & coverage</h2><div class="metricrow"><p><strong>{depthtext}</strong>Mean autosomal depth</p><p><strong>{covtext}</strong>Autosomal read coverage</p><p><strong>{mt_depth}</strong>Mean mitochondrial depth</p><p><strong>{mtcoverage:.1f}%</strong>Callable mitochondrial positions</p></div><h3>What these numbers mean</h3><p>Autosomal coverage measures bases with filtered reads. Mitochondrial callability also requires a dominant, sufficiently supported allele. Imputed marker callability is a separate measure and does not mean every base was sequenced.</p><p>At about 2× coverage, absence of a called rare variant is weak evidence of absence. Ancestry composition, mitochondrial lineage and clinical variant interpretation use different evidence rules.</p>{link('.mitochondrial_coverage.tsv','Download mitochondrial coverage')}{note('This report does not measure sample contamination or provide a clinical quality certificate.')}<details><summary>Original sequencing QC</summary><pre>{E(json.dumps(qc,indent=2))}</pre></details></section>'''
    methods='<section class="panel" id="methods" role="tabpanel" aria-labelledby="tab-methods" hidden><h2>Methods, sources & reproducibility</h2><p>The population model is a public research resource with six fixed components. The projection and chromosome intervals in this pipeline have computational tests, but have not been independently calibrated against known ancestry for low-pass sequencing. Results are exploratory.</p><ul>'+''.join('<li><a href="'+E(url)+'">'+E(label)+'</a></li>' for label,url in sources)+'</ul>'+link('.ancestry_explorer.json','Download full results and provenance')+'<details><summary>Pinned resource versions and checksums</summary><pre>'+E(json.dumps(data['resources'],indent=2))+'</pre></details></section>'
    script='''<script>const buttons=[...document.querySelectorAll('[data-tab]')];function show(id){if(!buttons.some(b=>b.dataset.tab===id))id='overview';for(const b of buttons)b.setAttribute('aria-selected',b.dataset.tab===id);for(const p of document.querySelectorAll('.panel'))p.hidden=p.id!==id;}for(const b of buttons)b.addEventListener('click',()=>{show(b.dataset.tab);history.replaceState(null,'','#'+b.dataset.tab)});show(location.hash.slice(1)||'overview');</script>'''
    (Path(folder)/(sample+'.ancestry_explorer.html')).write_text(head+nav+'</nav><main>'+overview+pop+maternal+ancient+quality_panel+methods+'</main><footer>Generated locally · sample '+E(sample)+' · No sample DNA uploaded to an ancestry service.</footer>'+script+'</body></html>')
